/* Edexcel IGCSE Geography past paper questions — Coastal Environments (Question 2). Login-protected (served under /igcse). */
window.SBL_IGCSE_PPQ = {"topic": "Coastal Environments", "img": "/igcse/geography/learn/past-papers-img/", "lessons": {"IGCO01": {"n": 1, "title": "What are the characteristics of waves?", "href": "/igcse/geography/learn/coastal-environments/l01-characteristics-of-waves"}, "IGCO02": {"n": 2, "title": "Processes of erosion, transportation and deposition", "href": "/igcse/geography/learn/coastal-environments/l02-erosion-transportation-deposition"}, "IGCO03": {"n": 3, "title": "Weathering and mass movement", "href": "/igcse/geography/learn/coastal-environments/l03-weathering-and-mass-movement"}, "IGCO04": {"n": 4, "title": "Geology, vegetation, people and sea level rise", "href": "/igcse/geography/learn/coastal-environments/l04-geology-vegetation-people-sea-level"}, "IGCO05": {"n": 5, "title": "Role of erosion and deposition in creating coastal landforms – Part 1", "href": "/igcse/geography/learn/coastal-environments/l05-headlands-bays-coves"}, "IGCO06": {"n": 6, "title": "Role of erosion and deposition in creating coastal landforms – Part 2", "href": "/igcse/geography/learn/coastal-environments/l06-cliffs-caves-arches-stacks"}, "IGCO07": {"n": 7, "title": "Role of erosion and deposition in creating coastal landforms – Part 3", "href": "/igcse/geography/learn/coastal-environments/l07-beaches-spits-bars"}, "IGCO08": {"n": 8, "title": "Distinctive ecosystems develop along particular stretches of coastline", "href": "/igcse/geography/learn/coastal-environments/l08-coastal-ecosystems"}, "IGCO09": {"n": 9, "title": "Coral reefs: a named coastal ecosystem", "href": "/igcse/geography/learn/coastal-environments/l09-coral-reefs"}, "IGCO10": {"n": 10, "title": "Threats to coastal ecosystems", "href": "/igcse/geography/learn/coastal-environments/l10-threats-to-coastal-ecosystems"}, "IGCO11": {"n": 11, "title": "Conflicts between users of the coast", "href": "/igcse/geography/learn/coastal-environments/l11-coastal-conflicts"}, "IGCO12": {"n": 12, "title": "Coastal flooding: causes, prediction and prevention", "href": "/igcse/geography/learn/coastal-environments/l12-coastal-flooding"}, "IGCO13": {"n": 13, "title": "Coastal management strategies: hard and soft engineering", "href": "/igcse/geography/learn/coastal-environments/l13-hard-and-soft-engineering"}, "IGCO14": {"n": 14, "title": "Coastal management case study: Sri Lanka", "href": "/igcse/geography/learn/coastal-environments/l14-sri-lanka-coastal-management"}, "IGCO15": {"n": 15, "title": "Coastal management case study: the Holderness coast, UK", "href": "/igcse/geography/learn/coastal-environments/l15-holderness-coastal-management"}}, "parts": [{"key": "2024-2a", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 2, "id": "2(a)", "marks": 1, "text": "Identify one abiotic characteristic of a coastal ecosystem.", "intro": "", "options": [["A", "coral"], ["B", "fungi"], ["C", "phytoplankton"], ["D", "temperature"]], "answer": "D", "type": "mcq", "lesson": "IGCO08", "ms": "AO1 (1 mark) (1)\n\nD (temperature)\n\nThe answer cannot be A, B or C as all biotic factors.", "sources": []}, {"key": "2024-2bi", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 2, "id": "2(b)(i)", "marks": 1, "text": "Identify the best definition of backwash.", "intro": "", "options": [["A", "distance between two wave crests"], ["B", "friction between wind and water surface"], ["C", "movement of water down the beach"], ["D", "movement of water up the beach"]], "answer": "C", "type": "mcq", "lesson": "IGCO01", "ms": "AO1 (1 mark) (1)\nC (movement of water down the beach)\n\nThe answer cannot be A (wavelength), B (cause of wave), D (swash).", "sources": []}, {"key": "2024-2bii", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 2, "id": "2(b)(ii)", "marks": 1, "text": "State one characteristic of a constructive wave.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO01", "ms": "AO1 (1 mark) (1)\nAward one mark for any of the following:\n\n• Long wavelength (1)\n• Short in height / shallow gradient (1)\n• Less frequent (1)\n• Gentle (1)\n• Deposition / low energy (1)\n• Strong(er) swash / weak(er) backwash (1)\n\nAccept any other appropriate response.", "sources": []}, {"key": "2024-2biii", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 2, "id": "2(b)(iii)", "marks": 2, "text": "Explain one type of coastal mass movement.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO03", "ms": "AO2 (2 marks) (2)\n\nAward 1 mark for identifying a type of mass movement and a further mark for further explanation up to a maximum of two marks.\n• Landslides / are large amounts of soil and rock (1) move down a slope due to gravity (1).\n• Rockfalls / when pieces of rock fall off a cliff face (1) often due to mechanical weathering (1).\n• Slumping occurs when saturated soil (1) flows down a curved surface (1).\n• Rotational slip (1) caused by erosion undercutting cliff (1).\nAccept any other appropriate response.", "sources": []}, {"key": "2024-2c", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 2, "id": "2(c)", "marks": 4, "text": "Study Figure 2a in the Resource Booklet. Suggest two reasons hard engineering is suitable for this stretch of coastline.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO13", "ms": "AO2 (2 marks)/AO3 (2 marks) (4)\n\nAward 1 mark (AO3) for the identification of a reason why hard engineering is suitable based on evidence from resources and a further mark for explanation (AO2) up to a maximum of two marks each.\n• There is a large urban area which has a high economic value (1) which would cost too much in compensation to not protect (1).\n• Claremont Pier suggests a tourist industry (1) this creates jobs for people living in the area (1).\n• In square 5594 there is a camping/caravan site (1) supporting the local economy (1).\n• There is a river mouth which is often used for trade (1) which needs to be kept clear to ensure boats can access (1).\n• A sea wall may be needed near Ness Point (1) to protect the buildings from flooding (1).\n• The beach is much narrower in 5594 (1) offering little coastal protection to the buildings without hard engineering (1).\n• There is a school in 5491 (1) which will negatively affect pupils education if erosion is allowed to take place (1).\nAccept any other appropriate response.", "sources": [{"src": "2024-q2-p37.jpg", "figs": ["2a"]}]}, {"key": "2024-2d", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 2, "id": "2(d)", "marks": 3, "text": "Explain why one conflict might occur between different users of coastlines.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO11", "ms": "AO2 (3 marks) (3)\nAward 1 mark for the identification of a conflict and 2 marks for further explanation up to a maximum of 3 marks.\n• Tourists are often in conflict with bird watchers (1) as they make a lot of noise (1) which can interrupt breeding grounds for coastal birds (1).\n• Governments are often in conflict with local residents (1) over the best type of coastal management strategy (1) as some are very expensive (1).\n• Hotel owners are often in conflict with fishing industry (1) as they leave broken fishing equipment causing pollution (1) which reduces tourist numbers (1).\n• Some users want to conserve the habitat (1) to increase tourism (1) and others want to develop ports for economic gain (1).\nAccept any other appropriate response.", "sources": []}, {"key": "2024-2e", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 2, "id": "2(e)", "marks": 1, "text": "Study Figure 2b in the Resource Booklet. Identify the landform labelled X.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO06", "ms": "AO3 (1 mark) (1)\n\nAward one mark for the following:\n• Arch (1)", "sources": [{"src": "2024-q2-p38.jpg", "figs": ["2b"]}]}, {"key": "2024-2f", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 2, "id": "2(f)", "marks": 4, "text": "Explain two physical factors that affect coastal deposition.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO07", "ms": "AO1 (2 marks)/AO2 (2 marks) (4)\n\nAward 1 mark (AO1) for the identification of a reason and a further mark for explanation (AO2) up to a maximum of two marks each.\n• Coasts with a low sediment supply (1) do not carry enough sediment to build up beaches (1).\n• Coastlines with deep water often have less deposition (1) as there is less friction with seabed (1).\n• Coastlines with mainly constructive waves increase deposition (1) because the swash is stronger than backwash (1).\n• Coastlines with sedimentary rocks often have high sediment supply (1) making depositional landforms more likely as waves have a high sediment load (1).\n• Sheltered areas of coastline / bays (1) often have constructive waves (1). Responses with reference to prevailing wind / longshore drift need to be linked to the depositional factor.\nDo not double credit direct mirrors.\nAccept any other appropriate response.", "sources": []}, {"key": "2024-2g", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 2, "id": "2(g)", "marks": 8, "text": "Study Figure 2c in the Resource Booklet. Analyse the possible reasons why the populations of some countries are more at risk from coastal flooding than others. You must refer to the resource in your answer.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO12", "ms": "AO3 (4 mark)/AO4 (4 mark) (8)\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the level-based mark scheme below.\nIndicative content guidance The indicative content below is not prescriptive, and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. This question is about analysing the different reasons why some areas of coastline are more at risk from coastal flooding. Candidates will need to be able to identify the areas at more risk and make judgements about why this is the case.\nAO3\n• Coastal flooding is when dry low-lying land is submerged by seawater.\n• Storm surges are likely to rise as a result of increased numbers of severe storm events due to more energy being in the atmosphere due to climate change.\n• Higher frequency of storm surges is likely to increase erosion rates which will make more areas vulnerable to coastal flooding.\n• Sea levels are predicted to rise due to melting ice sheets caused by increases in global temperatures.\n• Depositional landforms, such as spits and beaches, act as natural sea defences but can be destroyed by storms making areas more prone to flooding.\n• Coastal environments, such as mangroves and coral reefs, act as offshore barriers to storms but are both threatened by climate change and people increasing flood risk further.\n• Global population is still increasing which increases density of people living in coastal regions.\n• Coastal areas are often important for trade which is why populations can be high.\n• Asia is at greatest risk and this is significantly due to their population densities and tropical locations exposing them to more tropical storms.\n\nAO4\n\n• Figure 2c shows SE Asia is the area with the biggest population vulnerable to coastal flooding.\n• Figure 2c shows the USA has a large proportion of its population living in urban coastal areas.\n• Figure 2c shows China has experienced the biggest number of storm surges.\n• Figure 2c shows China has the biggest number of people at risk of coastal flooding.\n• Figure 2c shows the Philippines are an island nation exposing them to risk from multiple locations.\n• Figure 2c shows Egypt has a high population at risk of coastal flooding.\n\nLevel Mark Descriptor\n\n0 No rewardable material.\n\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\n\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)", "sources": [{"src": "2024-q2-p39.jpg", "figs": ["2c"]}]}, {"key": "2023-2a", "paper": "2023", "paperLabel": "June 2023 · Paper 1", "q": 2, "id": "2(a)", "marks": 1, "text": "Identify the coastal landform created by deposition.", "intro": "", "options": [["A", "cave"], ["B", "cliff"], ["C", "spit"], ["D", "wave-cut platform"]], "answer": "C", "type": "mcq", "lesson": "IGCO07", "ms": "AO1 (1 mark)\nC Spit\n\nThe answer cannot be A, B or D as these are all coastal landforms created by erosion.\n(1)", "sources": []}, {"key": "2023-2bi", "paper": "2023", "paperLabel": "June 2023 · Paper 1", "q": 2, "id": "2(b)(i)", "marks": 1, "text": "Identify the best definition of hydraulic action.", "intro": "", "options": [["A", "where waves pick up stones and they hit the cliffs"], ["B", "waves hit the cliffs forcing pockets of air into cracks"], ["C", "waves carry material along the coast"], ["D", "where rocks are dissolved by sea water"]], "answer": "B", "type": "mcq", "lesson": "IGCO02", "ms": "AO1 (1 mark)\n\nB Waves hit the cliffs forcing pockets of air into cracks.\n\nThe answer cannot be A (attrition), C (transportation/longshore drift) or D (solution).\n(1)", "sources": []}, {"key": "2023-2bii", "paper": "2023", "paperLabel": "June 2023 · Paper 1", "q": 2, "id": "2(b)(ii)", "marks": 1, "text": "State one type of weathering process.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO03", "ms": "AO1 (1 mark)\n\nAward 1 mark for any of the following.\n\n• Physical weathering / mechanical weathering (1).\n• Freeze-thaw weathering (1).\n• Onion-skin weathering (1).\n• Biological weathering (1).\n• Chemical weathering (1).\n\nAccept any other appropriate response.\n\nNo credit for ‘acid rain’\n(1)", "sources": []}, {"key": "2023-2c", "paper": "2023", "paperLabel": "June 2023 · Paper 1", "q": 2, "id": "2(c)", "marks": 2, "text": "Explain one way human activity can threaten coastal ecosystems.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO10", "ms": "AO1 (1 mark)/AO2 (1 mark)\nAward 1 mark (AO1) for initial point and a further mark for explanation of the reason (AO2) up to a maximum of two marks.\n• Pollution of (from tourist boats can pollute) the water (1) can damage coral reef ecosystems (1).\n• Deforestation of mangrove trees (1) can increase vulnerability during storm surges (1).\n• Overfishing/fishing (1) can reduce biodiversity in coastal ecosystems (1).\n• Climate change/greenhouse effect (1) can lead to coral bleaching (1).\n• Pollutes the sea (1) which can kill animals (1).\n\nAccept any other appropriate response.\n(2)", "sources": []}, {"key": "2023-2d", "paper": "2023", "paperLabel": "June 2023 · Paper 1", "q": 2, "id": "2(d)", "marks": 4, "text": "Study Figure 2a in the Resource Booklet. Explain two factors that could influence landforms on this coastline.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO04", "ms": "AO2 (2 marks)/AO3 (2 marks)\n\nAward 1 mark (AO3) for identification of any factor and a further mark for explanation of the reason (AO2) up to a maximum of two marks each.\n\n• Geology (1) as areas of soft rocks such as limestone are more easily eroded than hard rock areas (1).\n\n• Strength of prevailing winds (1) which can causes waves to erode more material from the coast (1).\n\n• Presence or absence of coastal management (1) to protect the coastal environment from erosion (1).\n\n• Vegetation present on the coastline (1) can cause erosion of cliffs through biological weathering (1).\n\n• Change in the direction of the coastline (1) can lead to spit formation 1).\n\nAccept any other appropriate response.\n\n(4)", "sources": [{"src": "2023-q2-p34.jpg", "figs": ["2a"]}]}, {"key": "2023-2e", "paper": "2023", "paperLabel": "June 2023 · Paper 1", "q": 2, "id": "2(e)", "marks": 3, "text": "Explain the process of longshore drift.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO02", "ms": "AO2 (3 marks)\n\nAward 1 mark for initial point and 2 marks for further explanation up to a maximum of 3 marks.\n\n• Prevailing wind blows waves to the beach at angle (1), the backwash then drags the sediment back to the sea (1) and the sediment is moved along the beach (1).\n\n• Swash carried materials up the beach at an angle to the coast (1) backwash carries it back down at rights angles to the coast (1) which carries material along the beach in a zig-zag pattern.\n\nAccept any other appropriate response.\n\n(3)", "sources": []}, {"key": "2023-2f", "paper": "2023", "paperLabel": "June 2023 · Paper 1", "q": 2, "id": "2(f)", "marks": 1, "text": "Study Figure 2b in the Resource Booklet. Identify the coastal management strategy shown.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO13", "ms": "AO3 (1 mark)\nAward 1 mark for the following:\n• Groynes (1).\n\n(1)", "sources": [{"src": "2023-q2-p35.jpg", "figs": ["2b"]}]}, {"key": "2023-2g", "paper": "2023", "paperLabel": "June 2023 · Paper 1", "q": 2, "id": "2(g)", "marks": 4, "text": "Explain one advantage and one disadvantage of soft engineering strategies.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO13", "ms": "AO1 (2 marks) AO2 (2 marks)\nAward 1 mark for initial point (AO1) for advantage and disadvantage and a further mark (AO2) for each. Only award marks for one advantage and one disadvantage up to maximum of 4 marks.\n• Advantages:\no Strategies such as managed retreat are cheaper than alternatives (1) because they do not involve building any new structures (1).\no Soft engineering protects the coast from erosion (1) as sand dune regeneration reduces the power of the waves (1).\no Beach replenishment which involves adding more sand to the beach (1) creates a natural defence against erosion.\no They look natural (1) which makes them more aesthetically pleasing (1).\n• Disadvantages:\no Strategies such as beach replenishment need to constantly be replaced (1) which can be expensive (1).\no Strategies such as beach reprofiling which involves moving sand towards the upper part of the beach (1) is not very effective against strong waves (1).\no Not as effective as hard engineering (1) as works with nature to reduce rather then prevent erosion (1).\no They can be considered ugly (1) when old sea defences are left to breakdown with managed retreat (1).\n\nAccept any other appropriate response.\n\n(4)", "sources": []}, {"key": "2023-2h", "paper": "2023", "paperLabel": "June 2023 · Paper 1", "q": 2, "id": "2(h)", "marks": 8, "text": "Study Figure 2c and Figure 2d in the Resource Booklet. Analyse the effectiveness of the coastal flood prevention strategies shown. Refer to the resources in your answer.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO12", "ms": "AO3 (4 marks) AO4 (4 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the level-based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive, and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. The question is about analysing the different coastal management strategies used and how effective they were at reducing risk from tropical cyclones in the region.\nAO3\n• Flood prevention often involves a mixture of hard (e.g., dams/levees/flood relief channels) and soft engineering strategies (e.g., flood warnings and preparation/ floodplain zoning/ecological flooding).\n• It is important that flood protection involves a mix of both soft and hard engineering in order to not only have structures to physically protect coast, but also mechanisms to ensure minimal risk to losing lives such as effective early warning systems which can allow people time to evacuate.\n• Coastlines are vulnerable to flooding due to tropical cyclones, storm surges and the impact of climate change.\n• Low lying coastlines are particularly at risk and so require hard engineering to protect them.\n\nAO4\n• Figure 2c shows how the whole coastline is at high risk of coastal flooding which justifies a mixture of different coastal prevention strategies.\n• Figure 2c indicates how coastlines are vulnerable to coastal floods (due to rain from Hurricane Katrina) which caused high levels of destruction which justifies high levels of investment in flood prevention strategies.\n• Figure 2d shows how flood prevention strategies have included flood walls, water pump stations and levees.\n• Figure 2d suggests that levees have been very expensive (US$14 billion after Hurricane Katrina) but may not provide long term protection.\nLevel Mark Descriptor\n\n0 No rewardable material.\n\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\n\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\n\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)", "sources": [{"src": "2023-q2-p36.jpg", "figs": ["2c"]}, {"src": "2023-q2-p37.jpg", "figs": ["2d"]}]}, {"key": "2023R-2a", "paper": "2023R", "paperLabel": "June 2023 · Paper 1R", "q": 2, "id": "2(a)", "marks": 1, "text": "Identify the soft engineering technique used on coastlines.", "intro": "", "options": [["A", "rock armour"], ["B", "groynes"], ["C", "sea wall"], ["D", "beach replenishment"]], "answer": "D", "type": "mcq", "lesson": "IGCO13", "ms": "AO1 (1 mark)\n\nD is the correct response Beach replenishment is the only soft engineering technique.\n\nThe answer cannot be A, B or C as these are all hard engineering techniques.\n\n(1)", "sources": []}, {"key": "2023R-2bi", "paper": "2023R", "paperLabel": "June 2023 · Paper 1R", "q": 2, "id": "2(b)(i)", "marks": 1, "text": "Identify the best definition of a coral reef ecosystem.", "intro": "", "options": [["A", "an ecosystem consisting of sandy deposits"], ["B", "an ecosystem made of small animals (polyps) living together in water with a temperature of 23–27°C"], ["C", "an ecosystem consisting of small shrubs and trees"], ["D", "an ecosystem where plants and animals are adapted to both salt and fresh water"]], "answer": "B", "type": "mcq", "lesson": "IGCO09", "ms": "AO1 (1 mark)\nB is the correct answer – this is the accurate definition of a coral reef ecosystem\nThe answer cannot be A (sand dune ecosystem), C (mangrove ecosystem), or D (salt marsh ecosystem).\n\n(1)", "sources": []}, {"key": "2023R-2bii", "paper": "2023R", "paperLabel": "June 2023 · Paper 1R", "q": 2, "id": "2(b)(ii)", "marks": 1, "text": "State one abiotic feature of an ecosystem.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO08", "ms": "AO1 (1 mark)\n\nAward 1 mark for a correct feature including:\n\n• light (1)\n• water levels (1)\n• salinity (1)\n• pH (1)\n• temperature (1)\n• soil (1)\n• rock type / geology (1)\n\nThe response is specifically about non-living elements of an ecosystem.\n\n(1)", "sources": []}, {"key": "2023R-2biii", "paper": "2023R", "paperLabel": "June 2023 · Paper 1R", "q": 2, "id": "2(b)(iii)", "marks": 2, "text": "Explain one factor that can affect the distribution of mangrove ecosystems.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO08", "ms": "AO1 (1 mark)/AO2 (1 mark)\n\nAward 1 mark for identifying factor (AO1) and a second mark for an appropriate development (AO2).\n\n• Salinity of water (1) as mangrove trees can grow in salty water (1).\n\n• Warm temperatures (1) as mangroves need water around 19oC (1).\n\n• Inter-tidal / shallow water / water depth (1) which allows the mangrove roots to grow above the water (1).\n\nAccept any other appropriate response.\n\n(2)", "sources": []}, {"key": "2023R-2c", "paper": "2023R", "paperLabel": "June 2023 · Paper 1R", "q": 2, "id": "2(c)", "marks": 4, "text": "Study Figure 2a in the Resource Booklet. Suggest two ways deposition can affect coastal landforms.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO07", "ms": "AO2 (2 mark)/AO3 (2 mark)\n\nAward 1 mark (AO2) for identification of how deposition affects the coastline (1) and a second mark for a further development (1) (AO3).\n\n• Beaches can increase in size (1) which creates greater protection against coastal erosion (1).\n\n• Deposition of sediment can cause a bar to form across a bay (1) which can lead to salt marsh formation behind the bar (1).\n\n• Deposition to form a beach / curved spit / tombolo (1) can protect coastlines absorbing the energy from the waves (1).\n\n• Deposition of sediment through longshore drift (1) can lead to the creation of a spit if the coastline changes direction (1).\n\nAccept any other appropriate response.\n\n(4)", "sources": [{"src": "2023R-q2-p34.jpg", "figs": ["2a"]}]}, {"key": "2023R-2d", "paper": "2023R", "paperLabel": "June 2023 · Paper 1R", "q": 2, "id": "2(d)", "marks": 3, "text": "Explain one factor that affects the rate of coastal erosion.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO04", "ms": "AO2 (3 marks)\nAward 1 mark for identification of a way and 2 marks for development and further explanation, up to a maximum of 3 marks. For example:\n\n• Geology of rocks will vary the hardness of the rock (1) this means that rocks will erode at different rates (1) resulting in variation in landforms in coastal areas (1).\n\n• Hard rock erodes more slowly (1) resulting in the formation in headlands or bays (or variation in coastal landforms) (1) as the surrounding rock is eroded more quickly (1).\n\n• Coastal protection (1) like a sea wall will decrease erosion (1) as it deflects the waves energy (1).\n\n• Sea level rise (1) can lead to waves attacking the cliff face more regularly (1) increasing rates of erosion (1).\n\n• Climate change (1) can increase the number of intense storms increasing frequency of destructive waves (1) which can increase erosion rates (1).\n\nAccept any other appropriate response.\n\n(3)", "sources": []}, {"key": "2023R-2e", "paper": "2023R", "paperLabel": "June 2023 · Paper 1R", "q": 2, "id": "2(e)", "marks": 1, "text": "Study Figure 2b in the Resource Booklet. Name the type of weathering taking place at X.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO03", "ms": "AO3 (1 mark)\n\nAward 1 mark for the following:\n\nBiological (weathering) (1)\n\n(1)", "sources": [{"src": "2023R-q2-p35.jpg", "figs": ["2b"]}]}, {"key": "2023R-2f", "paper": "2023R", "paperLabel": "June 2023 · Paper 1R", "q": 2, "id": "2(f)", "marks": 4, "text": "Explain the formation of a coastal arch.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO06", "ms": "AO1 (1 mark) / AO2 (3 marks)\n\nAward 1 mark for the initial point (AO1) and 3 further marks (AO2) for the extension of the point up to 4 marks.\n\n• Arches form at headlands (1)\n\n• Waves erode the base of the cliff either side of the headland (1)\n\n• This forms a cave on each side of the headland (1)\n\n• As the erosion continues caves become wider until the water breaks through the other side (1)\n\n• As further undercutting takes place the arch becomes wider and more developed (1)\n\nCandidates may develop further ideas around types of erosion acting on the headland.\n\nAccept any other appropriate response.\n\nCredit annotated diagrams.\n\n(4)", "sources": []}, {"key": "2023R-2g", "paper": "2023R", "paperLabel": "June 2023 · Paper 1R", "q": 2, "id": "2(g)", "marks": 8, "text": "Study Figure 2c and Figure 2d in the Resource Booklet. Analyse why conflicts between development and conservation occur in coastal areas. Refer to the resources in your answer.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO11", "ms": "AO3 (4 marks) AO4 (4 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the level based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. In this question the candidates will need to make the distinction between development and conservation. The resources identify the benefits of specifically developing tourism against the needs of conservationists.\nCandidates should explore both elements this would be expected in level 2 responses but maybe unbalanced.\nAO3\n• Development of tourism can work in partnership with conservation, but it is a delicate balance.\n\n• When coastal areas are badly managed conflict can result.\n\n• Coastal areas provide a clear opportunity for countries to develop their economies.\n\n• Commercialised fishing may have a negative effect on the coastal environment.\n\nAO4\n• Figure 2c suggests that tourism employs a large number of people in the Caribbean islands.\n\n• Figure 2c states that healthy oceans attract divers.\n\n• Figure 2c suggests that the development of Mangroves can also provide income through fishing to generate food and income for the local community.\n\n• Figure 2d suggests that coral reefs act as a barrier to storm surges protecting people and buildings.\n\n• Figure 2d suggests that mangroves reduce flood risk.\n\nLevel Mark Descriptor\n\n0 No rewardable material.\n\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\n\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\n\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)\nQuestion 3", "sources": [{"src": "2023R-q2-p36.jpg", "figs": ["2c", "2d"]}]}, {"key": "2022-2a", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 2, "id": "2(a)", "marks": 1, "text": "Identify the feature of a mangrove ecosystem.", "intro": "", "options": [["A", "high altitude"], ["B", "steep land gradient"], ["C", "complex root system"], ["D", "cold temperatures"]], "answer": "C", "type": "mcq", "lesson": "IGCO08", "ms": "AO1 (1 mark)\nC (complex root system)\n\nThe answer cannot be A (sand dune), B (shallow gradient at the coastline) or D (requires warm temperatures to grow)\n(1)", "sources": []}, {"key": "2022-2bi", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 2, "id": "2(b)(i)", "marks": 1, "text": "Identify a process of coastal erosion.", "intro": "", "options": [["A", "abrasion"], ["B", "beach"], ["C", "fetch"], ["D", "swash"]], "answer": "A", "type": "mcq", "lesson": "IGCO02", "ms": "AO1 (1 mark)\n\nA Abrasion (1)\nThe answer cannot be B (coastal landform), C or D (features of waves).\n(1)", "sources": []}, {"key": "2022-2bii", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 2, "id": "2(b)(ii)", "marks": 1, "text": "State one transportation process that occurs along a coastline.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO02", "ms": "AO1 (1 mark)\n\nAward 1 mark for any of the following.\n\n• Longshore drift (1)\n• Traction (1)\n• Saltation (1)\n• Solution (1)\n• Suspension (1)\n\nAccept any other appropriate response.\n(1)", "sources": []}, {"key": "2022-2c", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 2, "id": "2(c)", "marks": 2, "text": "Explain one way to reduce the impact of coastal flooding.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO12", "ms": "AO1 (1 mark)/AO2 (1 mark)\nAward 1 mark (AO1) for initial point and a further mark for explanation of the reason (AO2) up to a maximum of two marks.\n• Building designs such as being built on raised stilts (1) so they are above the level floods usually reach (1).\n• City and town planning that recognises which areas most at risk (1) and limits new building activity in these areas (1).\n• Including strategies for responding to coastal flood events in education programs (1) so people know how to respond, for example evacuation routes and shelters (1).\n• Using forecasting technologies (1) to be able to predict when coastal flooding will happen and evacuate before the event hits (1).\n• Building hard engineering strategies (sea walls) can reduce the energy/power of the waves (1) which can prevent damage to buildings (1).\n\nAccept any other appropriate response.\n(2)", "sources": []}, {"key": "2022-2d", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 2, "id": "2(d)", "marks": 4, "text": "Study Figure 2a in the Resource Booklet. Explain two reasons why there may be conflicts over the coastal management strategies chosen.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO11", "ms": "AO2 (2 marks)/AO3 (2 marks)\n\nAward 1 mark (AO3) for identification of any reason and a further mark for explanation of the reason (AO2) up to a maximum of two marks each.\n\n• Some areas of the coast are not being provided with any protection (1), so they are likely to experience faster rates of coastal erosion (1).\n\n• Those in Puerto Banus may resent people in Caleta de Velez (1) because they have a range of hard engineering strategies being used to protect the coastline (1).\n\n• Industry owners in El Zabal may feel their livelihood is more important to protect than fishing (1) and may not understand why there is not protection strategy there (1).\n\n• Building a sea wall is expensive (1) which means less money is spent on other services (1).\n\nAccept any other appropriate response.\n\n(4)", "sources": [{"src": "2022-q2-p33.jpg", "figs": ["2a"]}]}, {"key": "2022-2e", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 2, "id": "2(e)", "marks": 3, "text": "Explain one way climate change may affect coastal environments.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO12", "ms": "AO2 (3 marks)\n\nAward 1 mark for initial point and 2 marks for further explanation up to a maximum of 3 marks.\n\n• Climate change can cause the melting of ice caps (1) so global sea levels will rise (1) and so coastal settlements may become flooded or abandoned (1).\n\n• Climate change may cause increased coastal erosion (1) because sea levels are higher (1) and may be accompanied by more extreme weather events so more erosion (1).\n\n• Climate change could destroy coral reefs (1) because sea temperature rises (1) which leads to coral bleaching (1).\n\n• Climate change could increase severity of storms (1) which will increase erosion of mangroves (1) leading to loss of biodiversity (1).\n\nAccept any other appropriate response.\n\n(3)", "sources": []}, {"key": "2022-2f", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 2, "id": "2(f)", "marks": 1, "text": "Study Figure 2b in the Resource Booklet. Identify the type of wave shown.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO01", "ms": "AO3 (1 mark)\nAward 1 mark for the following:\n• Constructive wave (1).\n\n(1)", "sources": [{"src": "2022-q2-p34.jpg", "figs": ["2b"]}]}, {"key": "2022-2g", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 2, "id": "2(g)", "marks": 4, "text": "Explain the formation of a cave.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO06", "ms": "AO1 (1 mark) AO2 (3 marks)\nAward 1 mark for initial point (AO1) a further 3 marks for development of explanation (AO2) for each. Credit annotated diagrams where provided, but do not double credit ideas if repeated in the written text.\n\n• Cave forms along a headland (1). Wave action begins to erode the headland (1) especially where there are lines of weakness (1) repetition of this process leads to this line if weakness widening creating a cave (1).\n\nAccept any other appropriate response.\n\n(4)\n\nQuestion Indicative Content", "sources": []}, {"key": "2022-2h", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 2, "id": "2(h)", "marks": 8, "text": "Study Figure 2c in the Resource Booklet. Analyse the importance of managing the threats to this coral reef ecosystem.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO09", "ms": "AO3 (4 marks) AO4 (4 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the level-based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive, and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. The question is about analysing why the multiple threats to coral reef ecosystems is important.\nAO3\n• Coral reefs are delicate ecosystems that are subject to a range of physical and human threats.\n• For coral reefs to grow they need optimal conditions including lots of sunlight, and clear and shallow water around 21-29oC temperature. Climate change has the potential to increase water temperatures which could threaten coral growth, but there are a much wider range of threats from human activity.\n• Coral reefs are important for maintaining biodiversity in the ocean, and represent some of the most biologically diverse marine ecosystems on Earth. For example, the Great Barrier Reef contains over 400 coral species, 1,500 fish species, 4,000 mollusc species.\n• Coral reefs act as an important natural barrier for the coastline, which can reduce the power of waves hitting the coast.\n• Coral reefs are often popular sites for tourists to visit, and as such create jobs for many people in the tourist and hospitality industries which means it is important for economies that threats to them are reduced.\nAO4\n• Fig 2c shows how there are various threats to coral reef ecosystems.\n• Figure 2c indicates how human activities can threaten coral reef ecosystems through agriculture leading to increased pollution in the water which can affect coral growth.\n• Figure 2c indicates that pollution can reach water where corals are growing through groundwater flow.\n• Figure 2c indicates threats can include agriculture, road construction, oil and chemical spills, deforestation, stormwater runoff, coastal developments, chemicals from sunscreens as well leakages from septic tanks.\n• Figure 2c indicates how there are a range of stakeholders that are involved in the threats to coral reefs from tourists using sunscreens, up to city planners through plans for road construction.\n\nLevel Mark Descriptor\n\n0 No rewardable material.\n\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\n\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)", "sources": [{"src": "2022-q2-p35.jpg", "figs": ["2c"]}]}, {"key": "2021-2a", "paper": "2021", "paperLabel": "Summer 2021 · Paper 1", "q": 2, "id": "2(a)", "marks": 1, "text": "Identify the best definition of mechanical weathering.", "intro": "", "options": [["A", "Where rocks are broken down by physical factors in the environment."], ["B", "Where rocks are eroded by activities of plants and animals."], ["C", "Where rocks are protected from physical processes on a coastline."], ["D", "Where the chemical composition of the rocks is changed."]], "answer": "A", "type": "mcq", "lesson": "IGCO03", "ms": "AO1 (1 mark)\nA (Where the rocks are broken down by physical factors in the environment) (1).\n\nThe answer cannot be B (biological weathering), C (not a process), and D (chemical weathering).\n(1)", "sources": []}, {"key": "2021-2bi", "paper": "2021", "paperLabel": "Summer 2021 · Paper 1", "q": 2, "id": "2(b)(i)", "marks": 1, "text": "Identify an abiotic factor that affects coastal ecosystems.", "intro": "", "options": [["A", "Animals"], ["B", "Climate"], ["C", "Plants"], ["D", "Fungi"]], "answer": "B", "type": "mcq", "lesson": "IGCO08", "ms": "AO1 (1 mark)\n\nB (Climate) (1)\n\nThe answer cannot be A, C or D as these are all biotic features.\n\n(1)", "sources": []}, {"key": "2021-2bii", "paper": "2021", "paperLabel": "Summer 2021 · Paper 1", "q": 2, "id": "2(b)(ii)", "marks": 1, "text": "Identify one feature of coral reef ecosystems.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO09", "ms": "AO1 (1 mark)\n\nAward 1 mark for any of the following.\n\n• Calcium carbonate (1)\n• High levels of biodiversity (1)\n• Made of living organisms (1)\n• Home for lots of small fish (1)\n• Ideas around presence of tourism (1).\n• Idea of damage to Coral/ reef under threat idea (1).\n\nAccept any other appropriate response.\n(1)", "sources": []}, {"key": "2021-2biii", "paper": "2021", "paperLabel": "Summer 2021 · Paper 1", "q": 2, "id": "2(b)(iii)", "marks": 2, "text": "Explain one factor that controls the distribution of coral reef ecosystems.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO09", "ms": "AO1 (1 mark)/AO2 (1 mark)\nAward 1 mark (AO1) for initial point and a further mark for explanation of the factor (AO2) up to a maximum of two marks.\n• Temperature of the water (1) (tropical) coral needs optimum temperature of 25°c (1).\n• Temperature of the water (1) coral needs a minimum of 18°c degrees for growth (1).\n• Water depth (1) as coral needs less than 25m to survive (1).\n• Water depth (1) affects light penetration from sunlight (1).\n• Salinity (1) as corals are marine life and can only survive in saltwater (1).\n\nAccept any other appropriate response.\n(2)", "sources": []}, {"key": "2021-2c", "paper": "2021", "paperLabel": "Summer 2021 · Paper 1", "q": 2, "id": "2(c)", "marks": 4, "text": "Study Figure 2a in the Resource Booklet. Suggest two marine processes forming these coastal landforms.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO02", "ms": "AO2 (2 marks)/AO3 (2 marks)\n\nAward 1 mark (AO3) for identification of any factor from Fig 2a and a further mark for explanation of the reason (AO2) up to a maximum of two marks each.\n\n• Hydraulic action (1) where the force of the waves hit the cliffs forcing air into cracks (1).\n• Abrasion (1) where waves pick up stones which hit the cliff (1).\n• Corrosion/solution (1) where sea water dissolves rocks (1).\n• Arch is widened by the waves and then the roof collapses (1) stack formed as a result (1).\n• Stack attacked by wave action (1) worn down over time to form stump (1).\nAccept any other appropriate response.\n\n(4)", "sources": [{"src": "2021-q2-p29.jpg", "figs": ["2a"]}]}, {"key": "2021-2d", "paper": "2021", "paperLabel": "Summer 2021 · Paper 1", "q": 2, "id": "2(d)", "marks": 3, "text": "Explain one way industry can threaten coastal ecosystems.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO10", "ms": "AO2 (3 marks)\n\nAward 1 mark for the identification of a way in which industry can threaten coastal ecosystems and 2 marks for further explanation up to a maximum of 3 marks.\n\nCandidates could identify:\n\n• Dumping of industrial waste in the sea can cause water pollution (1) which can affect the biodiversity (1) and disrupt food chains (1).\n• The need to protect industry against coastal erosion (1) means that hard engineering strategies might be used (1) which can damage the natural habitat (1).\n• Building ports/infrastructure (1) can result in destruction of coastal environments (1) resulting in the loss of biodiversity (1).\n• Land reclamation for coastal development (1) can result in the destruction of coastal ecosystems (1) resulting in loss of biodiversity (1).\n• Tourist industry results in tourist scaring wildlife (1) which may have a negative impact on the coastal ecosystem (1).\nAccept any other appropriate response.\n\n(3)", "sources": []}, {"key": "2021-2e", "paper": "2021", "paperLabel": "Summer 2021 · Paper 1", "q": 2, "id": "2(e)", "marks": 1, "text": "Study Figure 2b in the Resource Booklet. Identify the feature labelled X.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO06", "ms": "AO3 (1 mark)\nAward 1 mark for the following:\n• Wave-cut platform (1)\n\n(1)", "sources": [{"src": "2021-q2-p30.jpg", "figs": ["2b"]}]}, {"key": "2021-2f", "paper": "2021", "paperLabel": "Summer 2021 · Paper 1", "q": 2, "id": "2(f)", "marks": 4, "text": "Explain how prevention strategies can reduce the impact of coastal flooding.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO12", "ms": "AO1 (1 mark) AO2 (3 marks)\nAward 1 mark for initial point (AO1), and 3 further marks (AO2) for the extension of this point up to maximum of 4 marks.\n\nCandidates may approach answering the question in different ways credit can be given for 2 developed. 1+1+1+1 Or 1+1 and 1+1\n• Prevention strategies such as flood defences built along to coastline (1) help to reduce the severity of flooding (1). Alternative strategies such as building emergency centres for people to shelter (1) reduce the amount of people who might be killed (1)\n• Prevention strategies such as restricting where buildings can be built/ building design (1) reduces the amount, of buildings that may be damaged in a flood event (1). This reduces the potential economic impact of a flood (1) and damaging less livelihoods (1).\n• Early warning systems (1) give messages through the coastguard/Environment agency (1) will help people prepare for the flood event/evacuate if necessary, to shelter spaces (1) preventing potential loss of life (1).\n\nAccept any other appropriate response.\n\n(4)", "sources": []}, {"key": "2021-2g", "paper": "2021", "paperLabel": "Summer 2021 · Paper 1", "q": 2, "id": "2(g)", "marks": 8, "text": "Study Figure 2c in the Resource Booklet. Analyse the different viewpoints affecting the decisions on coastal management strategies.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO11", "ms": "AO3 (4 marks) AO4 (4 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the level-based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive, and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. The question is about analysing the different coastal management strategies used on the coastline and how different groups of people have different priorities.\nAO3\n• The coastline is used by many different groups of people who can have conflicting views.\n• Residents and local businesses are likely to favour protecting the coastline where there are economic assets at stake.\n• There is a need to manage the different needs of the coastline. Where there are assets that need protecting implementing hard engineering strategies can be important.\n• Where there is important wildlife species or habitats, it is important to let nature proceed without intervention (soft engineering) to avoid disruption to natural processes, such as salt marsh formation.\n• There will be a difference of opinion between local residents and people who are visiting the area. Visitors are less likely to appreciate the value of hard engineering techniques in ensuring coastal erosion is minimised. Local people are likely to have positive view of hard engineering as it helps protect homes and businesses.\nAO4\n• Fig 2c shows how there are different coastal management strategies in place along the Dorset coastline.\n• Figure 2c demonstrates how urban areas e.g. Bournemouth need hard engineering strategies to protect the buildings that are located there.\n• Figure 2c shows how some areas of land have been allowed to retreat to allow natural processes to take over, creating a salt marsh.\n• Figure 2c demonstrates a range of conflicting views on the protection of the coastline based on the views of different groups of people.\n• Figure 2c shows a National nature reserve which will be focus for conservationists.\n\nCandidates may use compass bearings and scale to support their response.\nLevel Mark Descriptor\n\n0 No rewardable material.\n\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\n\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\n\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)", "sources": [{"src": "2021-q2-p31.jpg", "figs": ["2c"]}]}, {"key": "2019-2a", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 2, "id": "2(a)", "marks": 1, "text": "Identify the statement below that best describes the characteristics of a destructive wave.", "intro": "", "options": [["A", "long wavelength and weak backwash"], ["B", "short wavelength and strong backwash"], ["C", "long wavelength and strong backwash"], ["D", "short wavelength and weak backwash"]], "answer": "B", "type": "mcq", "lesson": "IGCO01", "ms": "AO1 (1 mark)\nB is the correct response short wavelength and strong backwash\n\nA is not correct as it describes a constructive wave\n\nC is not the correct answer as it describes only some elements of a destructive wave correctly\n\nD is not the correct answer as it describes only some elements of a destructive wave correctly\n\n(1)", "sources": []}, {"key": "2019-2bi", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 2, "id": "2(b)(i)", "marks": 1, "text": "Identify one erosional landform.", "intro": "", "options": [["A", "spit"], ["B", "cave"], ["C", "bar"], ["D", "beach"]], "answer": "B", "type": "mcq", "lesson": "IGCO06", "ms": "AO1 (1 mark)\nB is the correct answer - cave\n\nA,C and D are all depositional landforms\n\n(1)", "sources": []}, {"key": "2019-2bii", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 2, "id": "2(b)(ii)", "marks": 1, "text": "State one type of mass movement that affects coastal landscapes.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO03", "ms": "AO1 (1 mark)\n\nAward 1 mark for any of the following.\n\n• landslides (1)\n\n• slumping (1)\n\n• rock fall (1)\n\n• rotational slip (1)\n\n• sliding (1)\n\n• mud slides (1)\n\nAccept any other appropriate response (1)", "sources": []}, {"key": "2019-2biii", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 2, "id": "2(b)(iii)", "marks": 2, "text": "Explain one type of mechanical weathering that occurs at the coast.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO03", "ms": "AO1 (1 mark)/AO2 (1 mark)\n\nAward 1 mark (AO1) for a point about physical weathering and 1 mark (AO2) for further explanation, up to a maximum of 2 marks.\n• Freeze thaw (1) moisture in rock surfaces freezes and ex- pands causing rock to break off (1)\n• Onion-skin weathering / exfoliation (1)\n• Wetting and drying (1)\n\nAccept any other appropriate response\n\n(2)", "sources": []}, {"key": "2019-2c", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 2, "id": "2(c)", "marks": 4, "text": "Study Figure 2a in the Resource Booklet. Suggest two ways changes in sea level have created coastal landforms.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO04", "ms": "AO2 (2 mark)/AO3 (2 mark)\n\nAward 1 mark (AO2) for a way changes in sea level could have cre- ated a coastal landform and a further mark (AO3) for further devel- opment, shown on Figure 2a, up to a maximum of 2 marks each.\n\nThrough the reduction in sea level (1) a raised beach has been created (1). Changes in sea level have left behind raised beaches (1) and over time this new beach feature becomes vegetated. (1) Creation of wave cut notch (1) by marine erosion due to a re- duction in sea level there is an Due to a fall in sea level (1) old sea caves caves have been cre- ated (1) Changes in sea level have left behind old sea caves (1) with fos- silised remains of sea creatures (1) wave action from previous sea level has eroded cliff (1) to ex- pose fossilised remains / left behind old relic wave cut notches\n(1) Due to an increase in sea level (1) landforms such as rias /\n(4) fjords have been created (1)\nAccept any other appropriate response", "sources": [{"src": "2019-q2-p34.jpg", "figs": ["2a"]}]}, {"key": "2019-2d", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 2, "id": "2(d)", "marks": 3, "text": "Explain one physical factor that influences the distribution of mangrove ecosystems.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO08", "ms": "AO2 (3 marks)\n\nAward 1 mark for identification of a way and 2 marks for develop- ment and further explanation, up to a maximum of 3 marks. Temperature, light, water depth, salinity, wind direction, level of shelter. For example: Coastal mangroves need a high level of rainfall (1) of between 1500 and 3000 mm per annum (1) this can be ob- tained from rainfall or moisture in the air making tropical cli- mates ideal (1) Mangroves need a high temperature (1) around 27 degrees (1) otherwise they will not grow (1)\n\nMangroves need a shallow water (1) between 0.5 to 2.5 meters depth (1) but can survive where tidal ranges go slightly above or below this level (1) Mangroves need high levels of humidity (1) between 75 and 80% (1) to enable them to grow (1)\n\nAccept any other appropriate response\n\n(3)", "sources": []}, {"key": "2019-2e", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 2, "id": "2(e)", "marks": 1, "text": "Study Figure 2b in the Resource Booklet. Identify the coastal landform at X.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO06", "ms": "AO3 (1 mark)\n\nAward 1 mark for the following.\n\n• arch (1)\n\n(1)", "sources": [{"src": "2019-q2-p35.jpg", "figs": ["2b"]}]}, {"key": "2019-2f", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 2, "id": "2(f)", "marks": 4, "text": "Explain the formation of a headland.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO05", "ms": "AO1 (1 mark)/AO2 (3 mark)\n\nAward 1 mark for initial point (AO1), and 3 further marks (AO2) for the extension of this point up to maximum of 4 marks.\n\nHeadlands are formed along discordant coastlines (1) where there are bands of hard and soft rock at right angles to the coastline (1) which means that the soft rock gets eroded faster than hard rock (1) due to hydraulic action / creating a bay and a protruding headland (1)\n\nA Headland forms when waves attach a section of coastline (1) During the wave action soft rock erodes (1) more quickly than hard rock (1) over time this means that sections of hard rock are left protruding further out to see as the rest of the coastline retreats (1)\n\nAccept any other appropriate response\n\n(4)", "sources": []}, {"key": "2019-2g", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 2, "id": "2(g)", "marks": 8, "text": "Study Figure 2c and Figure 2d in the Resource Booklet. Analyse the reasons for the choice of different soft engineering strategies shown.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO13", "ms": "AO3 (4 marks) AO4 (4 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the level based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. This question is about investigating the issue of why different soft engineering techniques have been used. Candidates should be exploring cost, maintenance and suitability based on the map/resource evidence and their own knowledge.\n\nTo access level 3, both Figures 2c and 2d need to be used.\n\nAO3\n• Soft management techniques such as beach replenishment, building bars, cliff regrading\n• Managed retreat – abandoning certain areas of coastal defence and allow- ing nature to take its course\n• Candidates should be able to look at costs and benefits – this could be around cost/impact on the environment/local perception\n• Coastal defences create visual pollution in the area\n• Candidates may relate the type of technique used with the land use at the cost, they may also relate this to overall cost.\nAO4\n• Fig 2C shows different techniques have been used in different places\n• Fig 2C shows the offshore breakwater has been positioned to limit the ef- fects of the prevailing wind and dissipate the effect of the prevailing wind\n• Fig 2C shows the positioning beach nourishment to help lessen the effects of erosion\n• Fig 2D shows the type of soft engineering methods\n• Fig 2D demonstrates that cost/maintenance of the method of soft engi- neering methods\n• Fig 2D shows the relationship between soft engineering techniques and different land use types on the coast\n\nLevel Mark Descriptor\n\n0 No rewardable material.\n\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but un- derstanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judge- ments that are supported by limited evidence. (AO3)\n\n• Uses some geographical skills to obtain information with limited rele- vance and accuracy, which supports few aspects of the argument. (AO4)\n\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\n\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well-devel- oped argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)\nQuestion 3", "sources": [{"src": "2019-q2-p36.jpg", "figs": ["2c"]}, {"src": "2019-q2-p37.jpg", "figs": ["2c", "2d"]}]}, {"key": "2019R-2a", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 2, "id": "2(a)", "marks": 1, "text": "Identify the statement below that best describes the characteristics of a constructive wave.", "intro": "", "options": [["A", "long wavelength and weak backwash"], ["B", "short wavelength and strong backwash"], ["C", "long wavelength and strong backwash"], ["D", "short wavelength and weak backwash"]], "answer": "A", "type": "mcq", "lesson": "IGCO01", "ms": "AO1 (1 mark)\n\nA is the correct response long wavelength and weak backwash\n\nB is not correct as it describes a destructive wave.\n\nC is not the correct answer as it describes elements of a destructive wave.\n\nD is not the correct answer as it describes elements of a destructive wave. (1)", "sources": []}, {"key": "2019R-2bi", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 2, "id": "2(b)(i)", "marks": 1, "text": "Identify one depositional landform.", "intro": "", "options": [["A", "headland"], ["B", "spit"], ["C", "cave"], ["D", "stack"]], "answer": "B", "type": "mcq", "lesson": "IGCO07", "ms": "AO1 (1 mark)\nB is the correct answer - Spit\n\nOptions A,C and D are all erosional landforms.\n\n(1)", "sources": []}, {"key": "2019R-2bii", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 2, "id": "2(b)(ii)", "marks": 1, "text": "State one type of weathering that affects coastal landscapes.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO03", "ms": "AO1 (1 mark)\nAward one mark for:\n• Biological (1)\n• Physical / Mechanical (1)\n• Chemical (1)\n\nAlso allow named types of weathering that are linked to either physical, chemical or biological weathering, e.g.\n\n• Freeze thaw (1)\n• Plants and plat roots / burrowing animals (1)\n• Acid rain / solution / dissolving (1)\n• Onion-skin weathering / exfoliation (1)\nAccept other appropriate responses.\n\nReject rain or wind. (1)", "sources": []}, {"key": "2019R-2biii", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 2, "id": "2(b)(iii)", "marks": 2, "text": "Explain the process of longshore drift.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO02", "ms": "AO1 (1 mark)/AO2 (1 mark)\n\nAward 1 mark for accurately defining longshore drift (AO1) (1) and a second mark for an appropriate expansion (1)\n\nLongshore drift – this is the transportation of sediments along the coastline (1) in a zig zag pattern (1).\n\nAccept any other appropriate response.\n\n(2)", "sources": []}, {"key": "2019R-2c", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 2, "id": "2(c)", "marks": 4, "text": "Study Figure 2a in the Resource Booklet. Suggest two ways geology influences the shape of this coastline.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO04", "ms": "AO2 (2 marks)/AO3 (2 marks)\n\nAward 1 mark (AO2) for identification of how geology could affect the landscape (1) and a second mark for a further development (1) (AO3).\n• Hard and soft rocks will be eroded at different rates (1) changing the shape of the coastline so that there is a series of headlands and bays (1)\n• Rock jointing Where there is an increased amount of rock joints (1) there will be increased rates of erosion\n(1)\n• Soft rocks are eroded more quickly (1) so the coastline recedes more quickly creating bays (1).\n• Hard rock erodes more slowly (1) resulting in the formation of Headlands and other erosional features (1). Reward candidates for comments about shape of coastline not necessarily on the resource – e.g. steepness of slope. If candidates make hard and soft rock points as one way this only gains max two marks credit.\nAccept any other appropriate response.\n\n(4)", "sources": [{"src": "2019R-q2-p34.jpg", "figs": ["2a"]}]}, {"key": "2019R-2d", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 2, "id": "2(d)", "marks": 3, "text": "Explain one physical factor that influences the distribution of coral reef ecosystems.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO09", "ms": "AO3 (3 marks)\nAward 1 mark for identification of a way and 2 marks for development and further explanation, up to a maximum of 3 marks. Temperature, light, water depth, salinity, wind direction, level of shelter. For example:\n• Coral reefs need a minimum water temperature to develop (1) of around 18 degrees (1) they grow best between 23 and 25 degrees (1).\n• Coral reefs need a large amount of light (1) so levels of pollution have a negative effect (1) as the coral doesn’t have the correct nutrients to grow (1).\n• Coral reefs are sensitive to PH (1) they require a PH of 8\n– 8.5 (1) to grow sufficiently, maintain health (1).\n\nAccept any other appropriate response.\n\n(3)", "sources": []}, {"key": "2019R-2e", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 2, "id": "2(e)", "marks": 1, "text": "Study Figure 2b in the Resource Booklet. Identify the coastal landform X.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO06", "ms": "AO3 (1 mark)\n\nAward 1 mark for the following:\n\nStack (1)\n\n(1)", "sources": [{"src": "2019R-q2-p35.jpg", "figs": ["2b"]}]}, {"key": "2019R-2f", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 2, "id": "2(f)", "marks": 4, "text": "Explain the formation of a cliff.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO06", "ms": "AO1 (1 mark)/AO2 (3 marks)\n\nAward 1 mark for the initial point (AO1) and 3 further marks (AO2) for the extension of the point up to 4 marks.\n\n• Cliffs tend to be located on a headland due to erosion (1).\n• Destructive waves erode the base of the cliff due to repeated breaking (1).\n• Softer rock can erode more quickly than harder rock (1) leading to the formation of a wave cut notch (1). As further undercutting takes place the weight of the rock is to great and falls into the sea (1).\n• Cliffs are also shaped by surface weathering (1) the breaking down of rocks by subaerial processes (1). This include mechanical and biological weathering processes (1). accept freeze thaw, biological or chemical weathering\n• The rock type will affect cliff gradient or steepness (1). Cliffs which are gentle tend to be formed in areas where the geology is unconsolidated (1).\n• Cliff erosion can be by a number of methods (1) for example hydraulic action (1).\n\nAccept any other appropriate response.\n\n(4)", "sources": []}, {"key": "2019R-2g", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 2, "id": "2(g)", "marks": 8, "text": "Study Figure 2c and Figure 2d in the Resource Booklet. Analyse the reasons for the choice of the different hard engineering strategies shown.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCO13", "ms": "AO3 (4 marks) AO4 (4 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the level based mark scheme below.\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited.\nCandidates should explore both soft and hard management techniques as outlined in the resource. To access level 3, both Figures 2c and 2d must to be used.\nAO3\nNote: Candidates may refer to soft management techniques in their response this should be credited.\n• Soft management techniques such as beach replenishment, building bars, fencing hedging and replanting, cliff regrading:\n• Hard management – groynes, wooden revetment, steel wall, gabion and rip rap.\n• Managed retreat – abandoning certain areas of coastal defence and allowing nature to take its course.\n• Candidates should be able to look at costs and benefits – this could be around cost/impact on the environment /local perception.\n• Coastal defence’s create visual pollution in the area.\nAO4\n• Figure 2c shows different techniques have been used in different places.\n• Figure 2c shows that the techniques used in Photos 2 and 3 have been developed to protect the main headland this could be due to the positioning of a settlement,\n• Figure 2c shows the offshore breakwater has been positioned to limit the effects of the prevailing wind and dissipate the effect of the prevailing wind.\n• Figure 2c shows the positioning of groynes these are positioned in beach type areas and are more in keeping with the traditional approach to preventing longshore drift etc.\n• Figure 2d shows there is a range of costs of coastal management techniques.\n• Figure 2d shows that there are different maintenance costs.\n• Fig 2d suggests a relationship between the coastal management technique used and the type of coastal area.\n\nLevel Mark Descriptor\n\n0 No rewardable material.\n\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\n\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\n\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well- developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)\nQuestion 3", "sources": [{"src": "2019R-q2-p36.jpg", "figs": ["2c"]}, {"src": "2019R-q2-p37.jpg", "figs": ["2c", "2d"]}]}]};
